from urllib.parse import urlencode


def e(value):
    return html.escape(str(value), quote=True)


def item_list(items):
    return "<ul>" + "".join(f"<li>{e(x)}</li>" for x in items) + "</ul>"


def badge(text, kind="pending"):
    return f'<span class="badge {e(kind)}">{e(text)}</span>'


GAP_LINKS = {f"G{number:02d}": f"/remediation?gap=G{number:02d}#G{number:02d}" for number in range(1, 13)}


def gap_link(gap_id, label=None):
    """Only the twelve fixed gap identifiers can create a navigation URL."""
    label = gap_id if label is None else label
    return f'<a href="{GAP_LINKS[gap_id]}">{e(label)}</a>' if isinstance(gap_id, str) and gap_id in GAP_LINKS else e(label)


def dependency_links(identifiers, empty="No predecessor gap"):
    return ", ".join(gap_link(identifier) for identifier in identifiers) or e(empty)


def source_references(identifiers, evidence):
    """Map exact retained identifiers to positions in this captured index only."""
    indexed = {row["id"]: (position, row["label"]) for position, row in enumerate(evidence, 1)}
    references = []
    for identifier in identifiers:
        if identifier in indexed:
            position, label = indexed[identifier]
            reference = f'<a href="/evidence#source-{position:02d}">{e(identifier)} &middot; {e(label)}</a>'
        else:
            reference = f'<span class="source-reference-missing">{e(identifier)} &mdash; Not in this captured index</span>'
        references.append(f'<li>{reference}</li>')
    return '<ul class="source-references">' + "".join(references) + '</ul>'


def gap_card(gap, package, evidence=None, intake_configured=False, selected=False):
    dependencies = dependency_links(gap["dependencies"])
    matrix = "".join(f'<tr><th scope="row"><span class="requirement-id">{e(x["id"])}</span><br>{e(x["requirement"])}</th><td>{e(x["existing_coverage"])}</td><td>{e(x["required_receipt"])}</td><td>{e(x["verification_question"])}<br>{badge("Awaiting evidence")}</td></tr>' for x in package["evidence_matrix"])
    references = source_references(gap.get("source_ids", []), evidence or [])
    intake_link = f'<p><a href="/intake#intake-{gap["id"]}">View {e(gap["id"])} intake requirement checks</a></p>' if intake_configured and gap["id"] in GAP_LINKS else ""
    return f'''<details class="gap-card" id="{e(gap['id'])}" tabindex="-1"{" open" if selected else ""}><summary><span class="gap-id">{e(gap['id'])}</span><span class="gap-title">{e(gap['title'])}</span>{badge('Open', 'open')}<span class="priority">{e(gap['priority'])}</span></summary>
<div class="gap-content"><div class="state-line">{badge('Local package prepared', 'prepared')}<span>Substantive closure: <strong>pending</strong></span></div><p class="lead">{e(package['objective'])}</p>
<dl class="facts"><div><dt>Claim still blocked</dt><dd>{e(gap['blocked_decision_or_claim'])}</dd></div><div><dt>Dependencies</dt><dd>{dependencies}</dd></div><div><dt>Proposed roles</dt><dd>{e('; '.join(package['proposed_roles']))}</dd></div><div><dt>Agency owner / independent review / authority decision</dt><dd>Pending / pending / pending</dd></div></dl>
<h3>Existing evidence and its limits</h3><p>{e(gap['existing_evidence_and_limits'])}</p><h3>Captured source references</h3><p class="small">These links lead to captured index metadata only. They do not establish source availability, current publication, a supplied receipt or acceptance. An identifier absent from this index is not proof that its file is missing.</p>{references}{intake_link}<h3>Prepared local deliverables</h3>{item_list(package['deliverables'])}<h3>Evidence still required</h3>{item_list(package['required_evidence'])}<h3>Independent review checks</h3>{item_list(package['review_checks'])}
<h3>Receipt and verification matrix</h3><div class="table-scroll"><table><caption>Evidence requirements for {e(gap['id'])}; no receipt or verification has been supplied</caption><thead><tr><th>Requirement</th><th>Existing coverage</th><th>Required receipt</th><th>Verification question</th></tr></thead><tbody>{matrix}</tbody></table></div><h3>Unchanged substantive closure criteria</h3>{item_list(gap['closure_criteria'])}<p><strong>Next step:</strong> {e(gap['next_action'])}</p></div></details>'''



INTAKE_STATES = {"missing": "Missing", "partial": "Partially prepared", "complete_unverified": "Complete, unverified"}


def intake_field_link(code):
    """Only a fixed catalogue code can produce a field-guide fragment URL."""
    anchor = FIELD_ANCHORS.get(code) if isinstance(code, str) else None
    return f'<a href="/intake-guide#{anchor}"><code>{e(code)}</code></a>' if anchor is not None else e(code)


def intake_rows(rows, caption):
    """Only schema-approved identifiers, state and field/error codes are displayed."""
    rendered = []
    for row in rows:
        missing = ", ".join(intake_field_link(code) for code in row["missing_fields"]) or "None recorded"
        errors = ", ".join(row["errors"]) or "None recorded"
        rendered.append(f'<tr><th scope="row">{e(row["id"])}</th><td>{badge(INTAKE_STATES[row["state"]])}</td><td>{missing}</td><td>{e(errors)}</td></tr>')
    return f'<div class="table-scroll intake-table"><table><caption>{e(caption)}</caption><thead><tr><th>Item</th><th>Preparation state</th><th>Missing fields</th><th>Check codes</th></tr></thead><tbody>{"".join(rendered)}</tbody></table></div>'


def intake_page(intake):
    counts = intake["counts"]
    categories = (("Scope decisions", "scope", 11), ("Core appointments", "appointments", 4), ("Evidence requirements", "requirements", 36))
    count_rows = "".join(f'<tr><th scope="row">{e(label)} ({total})</th><td>{e(counts[prefix + "_missing"])}</td><td>{e(counts[prefix + "_partial"])}</td><td>{e(counts[prefix + "_complete_unverified"])}</td></tr>' for label, prefix, total in categories)
    draft = "This check records an uncompleted local draft." if intake["result"] == "incomplete" else "This check records locally prepared fields; every item remains unverified."
    title = "Incomplete local draft" if intake["result"] == "incomplete" else "Preparation complete, unverified"
    groups = []
    for group in intake["gap_summaries"]:
        gap_id = group["gap_id"]
        rows = [row for row in intake["requirements"] if row["gap_id"] == gap_id]
        dependencies = dependency_links(group["dependencies"])
        group_anchor = f' id="intake-{gap_id}"' if gap_id in GAP_LINKS else ""
        groups.append(f'<details class="gap-card intake-group"><summary{group_anchor}><span class="gap-id">{e(gap_id)}</span><span class="gap-title">Evidence requirement checks</span>{badge("Open", "open")}</summary><div class="gap-content"><p><strong>Dependencies:</strong> {dependencies}</p><p>{gap_link(gap_id, "Return to " + gap_id + " work package")}</p>{intake_rows(rows, gap_id + " · local field completeness only")}<p class="small">Completing these fields does not close this gap or satisfy its independent review criteria.</p></div></details>')
    bindings = intake["input_bindings"]
    return f'''<section class="intake-view" aria-labelledby="intake-heading"><p class="eyebrow">Local field completeness · no submission or approval</p><div class="section-top"><h2 id="intake-heading">Evidence intake check</h2>{badge(title)}</div><p class="lead">{draft} The check identifies missing response fields and evidence references. Field completeness never establishes authenticity, an appointment, independent review, acceptance or authority.</p><article class="notice"><strong>All 12 substantive gaps remain open.</strong> Agency decisions remain pending. No evidence has been accepted. Authorization effect: none.</article><h3>Preparation across the response</h3><div class="table-scroll intake-table"><table><caption>All expected items are retained; complete means complete and unverified</caption><thead><tr><th>Response group</th><th>Missing</th><th>Partially prepared</th><th>Complete, unverified</th></tr></thead><tbody>{count_rows}</tbody></table></div><p class="small">The check displays expected item identifiers, missing-field names and check codes. Submitted names, decisions, personal details and raw evidence values are not displayed.</p><details class="gap-card intake-group"><summary><span class="gap-title">Scope decisions · 11 checks</span>{badge("Agency decisions pending")}</summary><div class="gap-content">{intake_rows(intake["scope_decisions"], "Scope decision response fields; no decision is inferred")}</div></details><details class="gap-card intake-group"><summary><span class="gap-title">Core appointments · 4 checks</span>{badge("Appointments pending")}</summary><div class="gap-content">{intake_rows(intake["core_appointments"], "Appointment response fields; no appointment is inferred")}</div></details><h3>Evidence requirements by gap</h3><p>Open a gap to inspect each requirement's missing fields. These checks use the existing closure requirements without relaxing them.</p>{"".join(groups)}<article class="panel intake-provenance"><h3>Bound to this captured baseline</h3><dl class="facts"><div><dt>Check recorded at</dt><dd>{e(intake["checked_at"])}</dd></div><div><dt>Authorization effect</dt><dd>None</dd></div><div><dt>Baseline manifest SHA-256</dt><dd class="hash">{e(bindings["baseline_manifest_sha256"])}</dd></div><div><dt>Intake report manifest SHA-256</dt><dd class="hash">{e(intake["_manifest_sha256"])}</dd></div><div><dt>Response SHA-256</dt><dd class="hash">{e(bindings["response_sha256"])}</dd></div><div><dt>Evidence manifest SHA-256</dt><dd class="hash">{e(bindings["evidence_manifest_sha256"])}</dd></div></dl><p>Each request rechecks both pinned bundles. This verifies captured file integrity and report consistency; it does not verify the authority or truth of an external source.</p></article><div class="downloads"><a href="/api/intake-report">Download intake report JSON</a><a href="/api/intake-checklist">Download intake checklist Markdown</a></div></section>'''


def intake_guide_page():
    """Visible static definitions only; never submitted response values."""
    def definitions(fields):
        return "".join(f'<article class="field-definition" id="{FIELD_ANCHORS[code]}" tabindex="-1"><h3>{e(label)}</h3><p class="field-code"><code>{e(code)}</code></p><p>{e(explanation)}</p></article>' for code, label, explanation in fields)
    sections = '<section class="guide-group" id="common-fields" tabindex="-1"><h2>Common preparation fields</h2><p>These seventeen codes cover shared response metadata, draft appointments and requirement evidence. A missing-field code identifies what to prepare; it is not always the name of a new JSON property.</p>' + definitions(COMMON_FIELDS) + '</section>'
    for identifier, title, fields in SCOPE_GROUPS:
        sections += f'<section class="guide-group" id="scope-{identifier.lower()}" tabindex="-1"><h2>{e(identifier)} &middot; {e(title)}</h2><p>These fields belong inside the scope item and its existing <code>requested_fields</code> object. Their presence does not validate the adequacy or truth of the proposed scope.</p>{definitions(fields)}</section>'
    contents = '<a href="#common-fields">Common fields</a>' + "".join(f'<a href="#scope-{identifier.lower()}">{e(identifier)} &middot; {e(title)}</a>' for identifier, title, _ in SCOPE_GROUPS)
    return f'''<section class="field-guide" aria-labelledby="field-guide-heading"><p class="eyebrow">Draft preparation explanations &middot; read-only</p><h2 id="field-guide-heading">Intake field guide</h2><p class="lead">Use these explanations of the ninety-three known missing-field codes to prepare a separate draft. This page displays static guidance, not submitted names, identities, decisions or evidence values.</p><aside class="notice"><strong>All 12 substantive gaps remain open.</strong> Agency decisions and acceptance remain pending. Structural completeness means complete and unverified; it never establishes authenticity, truth, independence or authority.</aside><div class="two-col"><article class="panel"><h3>Prepare a separate copy</h3><p>Keep the original blank template and all prior evidence unchanged. Identify a new response revision, prepare only permitted draft metadata and declared attachments separately, and use the separate local intake checker to create a new report in a new output directory. The dashboard neither submits a response nor runs that checker.</p><p>Keep credentials, protected data and restricted identities out of the public local preparation package. Attachment presence and matching bytes do not authenticate the evidence or appoint a person.</p></article><article class="panel"><h3>Keep the draft structure and pending decisions</h3><p>Retain the template's exact keys, row identifiers, order and instructions. Scope, appointment and gap statuses remain <code>pending</code>; top-level <code>agency_decisions</code> and <code>agency_acceptance</code> remain <code>pending</code>, <code>authorization_effect</code> remains <code>none</code>, and <code>agency_practical_margin</code> and <code>protected_data_authority</code> remain <code>null</code>.</p><p>Gap <code>agency_owner</code>, <code>independent_review</code> and <code>authority_decision</code> remain <code>null</code>. Draft identities or evidence entries do not appoint anyone or grant approval.</p></article></div><section class="panel guide-rules" aria-labelledby="guide-rules-heading"><h3 id="guide-rules-heading">Read codes without changing the schema</h3><p>Scalar draft metadata accepts text up to 4,096 characters. Leave an unprepared scalar field <code>null</code>; blank text is treated as missing. Preserve the existing list fields and nested objects rather than replacing them with text.</p><p>A code such as <code>requested_fields.agency_reference</code> names the existing <code>agency_reference</code> entry inside that scope row's <code>requested_fields</code> object. Do not add a literal dotted key. <code>revision</code> refers to the one shared top-level response revision. <code>gap_evidence_references</code> is a synthetic missing-field code for the parent gap's existing evidence list, not a response property to add.</p><p>The six scalar attachment-identifier fields are <code>appointment_reference</code>, <code>accepted_remit_reference</code>, <code>conflict_declaration_reference</code>, <code>custodian_reference</code>, <code>independent_verification</code> and <code>evidence_reference</code>. They must resolve to declared attachment identifiers when supplied; names, paths and URLs do not substitute. Evidence lists contain unique identifiers present in the attachment manifest.</p><p>Only a requirement's <code>evidence_reference</code> identifier must also be in its parent gap's <code>evidence_references</code> list. That is the attachment identifier, not the <code>Gxx-Exx</code> requirement identifier; do not impose the same parent-list condition on custodian or reviewer identifiers. Other scope references, <code>accountable_role</code>, <code>exact_revision_reference</code> and <code>configuration_or_scope_revision</code> are ordinary draft text, not attachment-enforced identifiers.</p><p>Requested scope text is checked for presence and permitted metadata shape. The checker does not determine its adequacy, truth or legal meaning. No completed field chooses an accepted scientific threshold, supplies protected-data authority or changes a preserved finding.</p></section><nav class="guide-sections" aria-label="Field guide sections">{contents}</nav>{sections}<p><a href="/intake">Return to the captured intake check</a></p></section>'''


def handoff_page(handoff):
    """Display only the packet reader's sanitized, validated projection."""
    overview = handoff["overview"]
    bindings = overview["input_bindings"]
    inventory = handoff["inventory"]
    rows = "".join(f'<tr><th scope="row" class="path">{e(row["path"])}</th><td>{e(row["bytes"])}</td><td class="hash">{e(row["sha256"])}</td></tr>' for row in inventory)
    command = "python -B -m mra_readiness_handoff verify --archive review-packet.zip --archive-sha256 " + handoff["_archive_sha256"] + " --manifest-sha256 " + handoff["_manifest_sha256"] + " --baseline-manifest-sha256 " + bindings["baseline_manifest_sha256"] + " --intake-manifest-sha256 " + bindings["intake_manifest_sha256"]
    return f'''<section class="handoff-view" aria-labelledby="handoff-heading"><p class="eyebrow">Portable review preparation · no submission or acceptance</p><div class="section-top"><h2 id="handoff-heading">Review handoff</h2>{badge("Prepared, unaccepted")}</div><p class="lead">Download a fixed review packet that brings together the twelve open gaps, thirty-six evidence requirements, the redacted intake checks and all eighteen preserved comparison rows. The twelve unsupported comparison rows retain their null statistics.</p><article class="notice"><strong>All 12 substantive gaps remain open.</strong> This packet is not an agency response, a closed gap, independent custody or agency acceptance. Agency decisions remain pending. Authorization effect: none.</article><div class="two-col"><article class="panel"><h3>Prepared for local review</h3><p>The packet contains sanitized gap and work-package projections, preserved findings, metadata for captured evidence, the redacted intake report, provenance and input manifests. The intake retains all 51 expected items: 11 scope decisions, 4 appointments and 36 requirements.</p><p><a class="button" href="/api/review-handoff/archive">Download review packet</a></p><p class="small">The ZIP is a review copy. It cannot approve a response or execute a benchmark.</p></article><article class="panel"><h3>Privacy and evidence boundaries</h3><p>Raw responses, attachments, personal values, absolute source locations, original source bytes, models and scientific runtime files are omitted. The general advisory book is unchanged and is not included.</p><p>Logical filenames below identify packet contents. Original evidence remains separate; its indexed hashes are metadata, not a claim that original source bytes are bundled.</p></article></div><h3>Verify offline</h3><p>Use the separately installed local handoff toolkit to verify this downloaded packet against the archive and manifest pins below and its captured baseline and intake pins. Keep the expected pins in a separate trusted record. The ZIP does not include an executable verifier.</p><pre class="handoff-command"><code>{e(command)}</code></pre><p>Verification checks captured byte identity and known consistency rules. It does not establish independent custody, source authenticity, current publication, agency acceptance or legal authority.</p><article class="panel handoff-provenance"><h3>Pinned review copy</h3><dl class="facts"><div><dt>Captured baseline date</dt><dd>{e(overview["as_of"])}</dd></div><div><dt>Package status</dt><dd>Prepared, unaccepted · 12 open · 0 closed</dd></div><div><dt>Archive SHA-256</dt><dd class="hash">{e(handoff["_archive_sha256"])}</dd></div><div><dt>Packet manifest SHA-256</dt><dd class="hash">{e(handoff["_manifest_sha256"])}</dd></div><div><dt>Baseline manifest SHA-256</dt><dd class="hash">{e(bindings["baseline_manifest_sha256"])}</dd></div><div><dt>Intake manifest SHA-256</dt><dd class="hash">{e(bindings["intake_manifest_sha256"])}</dd></div></dl><p>Every request rechecks the baseline, the configured intake report and this packet. A mismatch disables the dashboard and its downloads until the pinned configuration is restored.</p></article><h3>Deterministic packet inventory</h3><p class="small">{e(len(inventory))} content files are listed by logical relative name. The downloaded manifest records this inventory; it is also included inside the ZIP.</p><div class="table-scroll handoff-table"><table><caption>Sanitized packet content, exact byte size and captured SHA-256</caption><thead><tr><th>Packet file</th><th>Bytes</th><th>SHA-256</th></tr></thead><tbody>{rows}</tbody></table></div><div class="downloads"><a href="/api/review-handoff/manifest">Download packet manifest JSON</a><a href="/api/review-handoff/readme">Download review instructions Markdown</a></div></section>'''


def tutorial_page(scenario_id=None, snapshot=None):
    configuration = scenario_config(scenario_id)
    selected = configuration['id']
    options = ''.join(f'<a href="/tutorial?scenario={identifier}"' + (' aria-current="page"' if selected == identifier else '') + f'>{e(title)}</a>' for identifier, title in SCENARIO_OPTIONS)
    def factors(rows):
        result = []
        for index, row in enumerate(rows):
            result.append(f'<details class="tutorial-factor"' + (' open' if index == 0 else '') + f'><summary><strong>{e(row["factor"])}</strong><span>{e(row["choice"])}</span></summary><div><p><strong>Why it matters:</strong> {e(row["reason"])}</p><p><strong>Evidence a real case would need:</strong> {e(row["evidence_needed"])}</p></div></details>')
        return '<div class="tutorial-factors">' + ''.join(result) + '</div>'
    status_labels = {'not_started':'Not yet illustrated', 'draft_illustration':'Draft illustration', 'review_illustration':'Review illustration', 'source_trace_illustration':'Source trace illustration', 'worked_illustration':'Worked illustration'}
    titles = {row['id']:row['title'] for row in snapshot['gap-register.json']['gaps']} if snapshot is not None else {}
    gaps = []
    for row in configuration['simulated']['gap_walkthrough']:
        gap_id = row['id']
        gaps.append(f'<details class="tutorial-gap" id="tutorial-{e(gap_id)}"><summary><span>{e(gap_id)} &middot; {e(titles.get(gap_id, "Checklist"))}</span><span class="tutorial-status">{e(status_labels[row["status"]])}</span></summary><div><p>{e(row["reason"])}</p><p><strong>Required in a real case:</strong> {e(row["real_receipt_needed"])}</p><p>{gap_link(gap_id, "Read the captured " + gap_id + " requirements, still open")}</p></div></details>')
    guide = configuration['guidance']
    return f'''<section class="tutorial-view" aria-labelledby="tutorial-heading"><p class="eyebrow">Fictional teaching configurations</p><h2 id="tutorial-heading">Choose a learning configuration</h2><p class="lead">Compare how decision maturity and source-evidence quality affect the questions a reviewer must resolve. Select an example to explore its assumptions and remaining evidence.</p><aside class="tutorial-notice"><strong>Demo / tutorial only &middot; public synthetic examples.</strong><p>Every decision, review and source record described here is fictional. Authentic source records are not included. These examples do not update the captured agency record, close a substantive gap, approve a deployment or run a benchmark.</p></aside><nav class="tutorial-selector" aria-label="Tutorial configurations">{options}</nav><article class="tutorial-selected" aria-labelledby="scenario-heading"><p class="eyebrow">Selected fictional configuration</p><h3 id="scenario-heading">{e(configuration['title'])}</h3><p class="lead">{e(configuration['summary'])}</p><p class="small">Live agency decisions: pending &middot; Original substantive gaps closed: none &middot; Authorization effect: none</p><h4>What this example teaches</h4>{item_list(configuration['learning_objectives'])}</article><h3>Decision configuration</h3><p>Open a factor to examine its fictional choice, the reasoning and the evidence a real decision would require.</p>{factors(configuration['simulated']['decision_configuration'])}<h3>Source-evidence configuration</h3><p>Traceability, original availability, definition consistency, rights and independent review are different questions. Every source example below is synthetic.</p>{factors(configuration['simulated']['source_configuration'])}<h3>Walk through the twelve gap checklists</h3><p class="small">Illustration states belong to this lesson only. They are not the state of the captured gaps or a claim that their closure criteria have been met. A complete worked example covers the questions without manufacturing a successful scientific result.</p>{''.join(gaps)}<div class="two-col tutorial-guidance"><article class="panel"><h3>Do</h3>{item_list(guide['do'])}</article><article class="panel"><h3>Do not</h3>{item_list(guide['dont'])}</article></div><article class="panel"><h3>Questions to carry into a real review</h3>{item_list(guide['next_questions'])}</article><aside class="notice"><strong>Preserved real findings remain unchanged.</strong> The recorded research verdict remains fail, with eighteen comparison rows and twelve unsupported null findings. Tutorial choices supply no new scientific evidence.</aside><div class="downloads"><a href="/tutorial-lab">Try the interactive decision and source worksheet</a><a href="/api/tutorial-config?scenario={e(selected)}">Download this synthetic tutorial configuration</a><a href="/remediation">Return to the captured open gaps</a></div><p class="small">The download uses a tutorial-specific schema. It is not an agency-response template and cannot be submitted as an operational intake response.</p></section>'''


def interactive_tutorial_page(assumptions=None, preset_id=None, snapshot=None):
    """A finite fictional GET worksheet; the captured record is never edited."""
    config = evaluate_assumptions(assumptions, preset_id)
    preset = config["preset_id"]
    baseline = evaluate_assumptions(None, preset)
    selected = {row["key"]: row for row in config["selected_controls"]}
    base_controls = {row["key"]: row for row in baseline["selected_controls"]}
    query = urlencode([("preset", preset)] + [(row["key"], row["value"]) for row in config["selected_controls"]])
    download = "/api/tutorial-lab-config?" + query
    preset_links = "".join(f'<a href="/tutorial-lab?preset={e(identifier)}#lab-workbench"' + (' aria-current="page"' if identifier == preset else '') + f'>{e(title)}</a>' for identifier, title in PRESET_OPTIONS)
    groups = (
        ("Fictional decision assumptions", ("purpose", "decision_review", "practical")),
        ("Synthetic source assumptions", ("definitions", "rights", "vintage", "source_review")),
        ("Scope and delivery assumptions", ("protected_scope", "custody", "operations", "pilot", "governance")),
    )
    fields = []
    metadata = {row["key"]: row for row in CONTROL_OPTIONS}
    for legend, keys in groups:
        items = []
        for key in keys:
            row, current = metadata[key], selected[key]
            options = "".join(f'<option value="{e(value)}"' + (' selected' if value == current["value"] else '') + f'>{e(label)}</option>' for value, label in row["options"])
            items.append(f'<div class="lab-control"><label for="assumption-{e(key)}">{e(row["label"])}</label><select id="assumption-{e(key)}" name="{e(key)}" aria-describedby="help-{e(key)}">{options}</select><div id="help-{e(key)}"><p class="small">{e(row["description"])}</p><p><strong>Current illustrated assumption:</strong> {e(current["reason"])}</p></div></div>')
        fields.append(f'<fieldset><legend>{e(legend)}</legend><div class="lab-controls">{"".join(items)}</div></fieldset>')
    changed = [row for row in config["selected_controls"] if row["value"] != base_controls[row["key"]]["value"]]
    changes = item_list([row["label"] + ": " + row["value_label"] for row in changed]) if changed else '<p>No assumptions differ from the loaded starting configuration.</p>'
    labels = {"illustrated": "Illustrated assumption", "unresolved": "Unresolved in this lesson", "conflict": "Conflicting assumption", "authentic_receipt_required": "Authentic receipt still required"}
    originals = {row["id"]: row for row in baseline["simulated"]["gap_checklists"]}
    cards, links = [], []
    for gap in config["simulated"]["gap_checklists"]:
        identifier = gap["id"]
        base_rows = {row["factor"]: row for row in originals[identifier]["checklist"]}
        effects = [row["factor"] for row in gap["checklist"] if row != base_rows.get(row["factor"])]
        effect_text = "Changed checkpoints: " + "; ".join(effects) if effects else "The checklist reasoning matches the loaded starting configuration."
        checks = "".join(f'<li class="lab-check {e(row["state"])}"><strong>{e(row["factor"])}</strong><span class="lab-check-state">{e(labels.get(row["state"], row["state"]))}</span><p>{e(row["reason"])}</p></li>' for row in gap["checklist"])
        links.append(f'<li><a href="#lab-{e(identifier)}"><strong>{e(identifier)}</strong> {e(gap["title"])}</a><span>{e(gap["label"])}</span></li>')
        cards.append(f'<article class="lab-gap {e(gap["state"])}" id="lab-{e(identifier)}" tabindex="-1"><div class="section-top"><h3>{e(identifier)} · {e(gap["title"])}</h3><span class="lab-lesson-state">{e(gap["label"])}</span></div><p>{e(gap["reason"])}</p><p class="lab-effect"><strong>Effect relative to the loaded preset:</strong> {e(effect_text)}</p><ul class="lab-checks">{checks}</ul><aside class="notice"><strong>Real {e(identifier)} remains open. Authentic receipt not supplied.</strong><p>{e(gap["real_receipt_needed"])}</p></aside><p>{gap_link(identifier, "Read the captured " + identifier + " requirements, still open")}</p></article>')
    guide = config["guidance"]
    return f'''<section class="lab-view" aria-labelledby="lab-heading"><p class="eyebrow">Interactive fictional worksheet</p><h2 id="lab-heading">Change assumptions. Examine the reasons.</h2><p class="lead">Use the fictional Service Planning Office case to explore how decisions and source assumptions interact. Change a choice, then select Update illustration. The resulting checklists explain aligned assumptions, unanswered questions and conflicts.</p><aside class="tutorial-notice"><strong>Demo only · all choices and source descriptions are fictional.</strong><p>No authentic source records, appointments, approvals or measured results are supplied. Real agency decisions remain pending; all twelve substantive gaps remain open. The worksheet changes a lesson displayed in this browser, with no saved response or agency submission.</p></aside><h3>Load a starting configuration</h3><nav class="tutorial-selector" aria-label="Interactive tutorial starting configurations">{preset_links}</nav><p class="small">Loading a starting configuration replaces the fictional choices below. You can then combine the assumptions independently.</p><form id="lab-workbench" method="get" action="/tutorial-lab#lab-results"><input type="hidden" name="preset" value="{e(preset)}">{"".join(fields)}<div class="lab-actions"><button type="submit">Update illustration</button><a href="/tutorial-lab?preset={e(preset)}#lab-workbench">Reset to this starting configuration</a><a href="#lab-results">Go to the current checklist effects</a></div><p class="small">Changes take effect when you select Update illustration. Only these fixed fictional options are accepted.</p></form><section id="lab-results" class="lab-results" aria-labelledby="lab-results-heading" tabindex="-1"><p class="eyebrow">Fictional checklist effects</p><h2 id="lab-results-heading">How the selected assumptions affect the checklists</h2><p>Aligned lesson assumptions describe internal reasoning only. They do not establish source authenticity, scientific performance, deployed controls or agency acceptance. An unresolved empirical-evidence checkpoint remains in G05 and G06 under every configuration.</p><article class="panel"><h3>Changes from the loaded starting configuration</h3>{changes}</article><p class="small">Real agency decisions: pending · Real substantive gaps: twelve open · Authorization effect: none · Benchmark executed: no</p><ul class="lab-index">{"".join(links)}</ul>{"".join(cards)}</section><div class="two-col tutorial-guidance"><article class="panel"><h3>Do</h3>{item_list(guide["do"])}</article><article class="panel"><h3>Do not</h3>{item_list(guide["dont"])}</article></div><article class="panel"><h3>Questions for a real review</h3>{item_list(guide["next_questions"])}</article><aside class="notice"><strong>Preserved real findings remain unchanged.</strong> The recorded verdict remains fail, with eighteen comparison rows and twelve unsupported null findings. Fictional choices provide no new scientific evidence.</aside><div class="downloads"><a href="/tutorial-compare">Compare two fictional configurations side by side</a><a href="{e(download)}">Download these synthetic assumptions and checklist explanations</a><a href="/tutorial">Read the fixed tutorial examples</a><a href="/remediation">Return to the captured open gaps</a></div><p class="small">The download is teaching material in a separate interactive tutorial format. Authentic evidence and actual decisions are still required in a real case.</p></section>'''


def comparison_tutorial_page(left_assumptions=None, right_assumptions=None, left_preset=None, right_preset=None, snapshot=None):
    """Pair two independent fictional worksheets without changing real records."""
    config = evaluate_comparison(left_assumptions, right_assumptions, left_preset, right_preset)
    left, right = config["left"], config["right"]
    def full_query(a, b):
        values = [("left_preset", a["preset_id"]), ("right_preset", b["preset_id"])]
        for side, item in (("left", a), ("right", b)):
            values.extend((side + "_" + row["key"], item["assumptions"][row["key"]]) for row in CONTROL_OPTIONS)
        return urlencode(values)
    query = full_query(left, right)
    panels = []
    groups = (
        ("Decision assumptions", ("purpose", "decision_review", "practical")),
        ("Source assumptions", ("definitions", "rights", "vintage", "source_review")),
        ("Scope and delivery assumptions", ("protected_scope", "custody", "operations", "pilot", "governance")),
    )
    metadata = {row["key"]: row for row in CONTROL_OPTIONS}
    for side, letter, item, opposite in (("left", "A", left, right), ("right", "B", right, left)):
        selected = {row["key"]: row for row in item["selected_controls"]}
        links = []
        for identifier, title in PRESET_OPTIONS:
            load = [("left_preset", identifier if side == "left" else left["preset_id"]), ("right_preset", identifier if side == "right" else right["preset_id"])]
            other_side = "right" if side == "left" else "left"
            load.extend((other_side + "_" + row["key"], opposite["assumptions"][row["key"]]) for row in CONTROL_OPTIONS)
            links.append(f'<a href="/tutorial-compare?{e(urlencode(load))}#comparison-workbench"' + (' aria-current="page"' if identifier == item["preset_id"] else '') + f'>{e(title)}</a>')
        fields = []
        for legend, keys in groups:
            controls = []
            for key in keys:
                meta, current = metadata[key], selected[key]
                options = "".join(f'<option value="{e(value)}"' + (' selected' if value == current["value"] else '') + f'>{e(label)}</option>' for value, label in meta["options"])
                control_id = "assumption-" + side + "-" + key
                help_id = "help-" + side + "-" + key
                controls.append(f'<div class="compare-control"><label for="{e(control_id)}">{e(letter)}: {e(meta["label"])}</label><select id="{e(control_id)}" name="{e(side + "_" + key)}" aria-describedby="{e(help_id)}" title="{e(current["value_label"])}">{options}</select><div id="{e(help_id)}"><p class="small">{e(meta["description"])}</p><p class="small"><strong>Current illustrated choice:</strong> {e(current["value_label"])}</p></div><details class="compare-choice-reason"><summary>Reason for this illustrated choice</summary><p>{e(current["reason"])}</p></details></div>')
            fields.append(f'<fieldset><legend>{e(legend)}</legend>{"".join(controls)}</fieldset>')
        panels.append(f'<section class="compare-config" aria-labelledby="configuration-{e(side)}"><h3 id="configuration-{e(side)}">Configuration {e(letter)}</h3><p class="small">Loaded from: {e(item["preset_title"])}</p><div class="compare-presets" role="group" aria-label="Configuration {e(letter)} starting presets">{"".join(links)}</div>{"".join(fields)}</section>')
    difference_labels = {
        "same_checklist": "Same checklist",
        "checkpoint_differences": "Same lesson label, different checkpoints",
        "state_and_checkpoint_differences": "Different lesson labels and checkpoints",
    }
    checkpoint_labels = {"illustrated": "Illustrated assumption", "unresolved": "Unresolved in this lesson", "conflict": "Conflicting assumption", "authentic_receipt_required": "Authentic receipt still required"}
    changed = []
    for row in config["changed_controls"]:
        changed.append(f'<article class="compare-assumption"><h4>{e(row["label"])}</h4><div class="compare-columns"><p><strong>A:</strong> {e(row["left"]["value_label"])}</p><p><strong>B:</strong> {e(row["right"]["value_label"])}</p></div></article>')
    changes = "".join(changed) if changed else '<p>Both sides use the same effective assumptions. Different preset names or side placement alone do not change a checklist.</p>'
    index, cards = [], []
    for gap in config["comparison"]["gap_checklists"]:
        identifier = gap["id"]
        difference = difference_labels[gap["difference_kind"]]
        index.append(f'<li><a href="#compare-{e(identifier)}"><strong>{e(identifier)}</strong> {e(gap["title"])}</a><span>{e(difference)}</span></li>')
        side_headings = []
        for side, letter in (("left", "A"), ("right", "B")):
            row = gap[side]
            side_headings.append(f'<div><h4>Configuration {e(letter)}</h4><span class="lab-lesson-state">{e(row["label"])}</span><p>{e(row["reason"])}</p></div>')
        pairs = []
        for pair in gap["checkpoint_pairs"]:
            columns = []
            for side, letter in (("left", "A"), ("right", "B")):
                row = pair[side]
                if row is None:
                    cell = f'<p class="compare-absent">This conditional checkpoint is not triggered by configuration {e(letter)}. Authentic evidence remains absent and the real gap remains open.</p>'
                else:
                    cell = f'<span class="lab-check-state">{e(checkpoint_labels.get(row["state"], row["state"]))}</span><p>{e(row["reason"])}</p>'
                columns.append(f'<div class="compare-check-cell"><h5>Configuration {e(letter)}</h5>{cell}</div>')
            difference_marker = "Different checkpoint conditions" if pair["different"] else "Same checkpoint conditions"
            pairs.append(f'<section class="compare-check-pair' + (' different' if pair["different"] else '') + f'"><h4>{e(pair["factor"])}</h4><p class="small"><strong>{e(difference_marker)}.</strong> {e(pair["explanation"])}</p><div class="compare-columns">{"".join(columns)}</div></section>')
        changed_here = item_list([row["label"] + " — A: " + row["left"]["value_label"] + "; B: " + row["right"]["value_label"] for row in gap["changed_controls"]]) if gap["changed_controls"] else '<p class="small">No differing selected control is referenced by this checklist.</p>'
        receipts = "".join(f'<div><h4>Configuration {letter}: real {e(identifier)} remains open</h4><p>Authentic receipt not supplied. {e(gap[side]["real_receipt_needed"])}</p></div>' for side, letter in (("left", "A"), ("right", "B")))
        cards.append(f'<article class="comparison-gap" id="compare-{e(identifier)}" tabindex="-1"><div class="section-top"><h3>{e(identifier)} · {e(gap["title"])}</h3><span class="comparison-difference">{e(difference)}</span></div><p>{e(gap["explanation"])}</p><h4>Differing assumptions referenced here</h4>{changed_here}<div class="compare-columns comparison-gap-summary">{"".join(side_headings)}</div>{"".join(pairs)}<aside class="notice"><div class="compare-columns">{receipts}</div></aside><p>{gap_link(identifier, "Read the captured " + identifier + " requirements, still open")}</p></article>')
    guide = config["guidance"]
    reset = "/tutorial-compare?" + urlencode([("left_preset", left["preset_id"]), ("right_preset", right["preset_id"])]) + "#comparison-workbench"
    swap = "/tutorial-compare?" + full_query(right, left) + "#comparison-results"
    download = "/api/tutorial-comparison?" + query
    return f"""<section class="comparison-view" aria-labelledby="comparison-heading"><p class="eyebrow">Two fictional configurations</p><h2 id="comparison-heading">Compare decisions and source assumptions</h2><p class="lead">Keep one side fixed while changing the other, or edit both. Each uses the fictional Service Planning Office case. Select Update comparison to pair the resulting checklist conditions and read their reasons.</p><aside class="tutorial-notice"><strong>Teaching comparison only · both sides are fictional.</strong><p>Neither configuration supplies authentic source records, appointments, approvals or measured results. Real agency decisions remain pending and all twelve substantive gaps remain open. Differences describe lesson assumptions, with no preferred configuration or readiness score.</p></aside><p class="walkthrough-entry"><a class="button" href="/tutorial-walkthrough">Start the guided comparison walkthrough</a> <a class="button" href="/tutorial-practice">Try guided practice</a></p><p><a href="/tutorial-lab">Return to the single-configuration interactive worksheet</a></p><form id="comparison-workbench" method="get" action="/tutorial-compare#comparison-results"><input type="hidden" name="left_preset" value="{e(left["preset_id"])}"><input type="hidden" name="right_preset" value="{e(right["preset_id"])}"><p class="small">Each preset link replaces that side's illustrated choices and preserves the opposite side. Apply edited choices before using preset, swap or reset links; those links use the current illustration.</p><div class="compare-columns compare-workbench">{"".join(panels)}</div><div class="lab-actions"><button type="submit">Update comparison</button><a href="{e(swap)}">Swap illustrated A and B</a><a href="{e(reset)}">Reset both to their loaded presets</a><a href="#comparison-results">Go to the current comparison</a></div><p class="small">Changes take effect when you select Update comparison. No response is saved or submitted to an agency.</p></form><section id="comparison-results" class="comparison-results" aria-labelledby="comparison-results-heading" tabindex="-1"><p class="eyebrow">Paired checklist explanations</p><h2 id="comparison-results-heading">How the two configurations differ</h2><p>Compare the checkpoint reasons as well as the lesson labels. Both sides can have the same label while different assumptions affect their checklists. A conditional checkpoint that is not triggered supplies no evidence.</p><p class="small">Real agency decisions: pending · Real substantive gaps: twelve open · Authorization effect: none · Benchmark executed: no</p><h3>Different selected assumptions</h3>{changes}<ul class="lab-index">{"".join(index)}</ul>{"".join(cards)}</section><div class="two-col tutorial-guidance"><article class="panel"><h3>Do</h3>{item_list(guide["do"])}</article><article class="panel"><h3>Do not</h3>{item_list(guide["dont"])}</article></div><article class="panel"><h3>Questions for a real review</h3>{item_list(guide["next_questions"])}</article><aside class="notice"><strong>Preserved findings remain unchanged on both sides.</strong> The recorded verdict remains fail, with eighteen comparison rows and twelve unsupported null findings. Empirical evidence remains unresolved in G05 and G06 under every configuration.</aside><div class="downloads"><a href="{e(download)}">Download the synthetic comparison and both configurations</a><a href="/remediation">Return to the captured open gaps</a></div></section>"""



def guided_comparison_page(step=None, snapshot=None):
    '''Explain fixed lesson pairs; navigation never records a completed review.'''
    lesson = evaluate_walkthrough(step)
    difference_labels = {
        "same_checklist": "Same checklist",
        "checkpoint_differences": "Same lesson label, different checkpoints",
        "state_and_checkpoint_differences": "Different lesson labels and checkpoints",
    }
    checkpoint_labels = {"illustrated": "Illustrated assumption", "unresolved": "Unresolved in this lesson", "conflict": "Conflicting assumption", "authentic_receipt_required": "Authentic receipt still required"}
    def lesson_url(identifier):
        return "/tutorial-walkthrough?" + urlencode({"step": identifier}) + "#walkthrough-lesson"
    steps = "".join(f'<a href="{e(lesson_url(identifier))}"' + (' aria-current="step"' if identifier == lesson["id"] else '') + f'><span>{position}</span> {e(title)}</a>' for position, (identifier, title) in enumerate(STEP_OPTIONS, 1))
    actions = []
    if lesson["previous_id"] is not None:
        actions.append(f'<a href="{e(lesson_url(lesson["previous_id"]))}">Previous lesson</a>')
    if lesson["next_id"] is not None:
        actions.append(f'<a class="button" href="{e(lesson_url(lesson["next_id"]))}">Next lesson</a>')
    else:
        actions.append(f'<a class="button" href="{e(lesson["workbench_form_url"])}">Continue exploring in the comparison</a>')
    actions.append('<a href="/tutorial-walkthrough#walkthrough-lesson">Restart walkthrough</a>')
    movement = '<div class="walkthrough-actions">' + "".join(actions) + '</div>'
    selected = lesson["comparison"]
    assumptions = []
    for row in selected["changed_controls"]:
        assumptions.append(f'<li><strong>{e(row["label"])}</strong><div class="compare-columns"><p><strong>A:</strong> {e(row["left"]["value_label"])}</p><p><strong>B:</strong> {e(row["right"]["value_label"])}</p></div></li>')
    choices = '<ul class="walkthrough-choices">' + "".join(assumptions) + '</ul>' if assumptions else '<p>Both configurations use the same effective assumptions. Read the shared missing evidence as well as the matching lesson labels.</p>'
    summaries = []
    for gap in selected["comparison"]["gap_checklists"]:
        identifier = gap["id"]
        summaries.append(f'<tr><th scope="row"><a href="{e(lesson["per_gap_urls"][identifier])}">{e(identifier)} · {e(gap["title"])}</a></th><td>{e(gap["left"]["label"])}</td><td>{e(gap["right"]["label"])}</td><td><strong>{e(difference_labels[gap["difference_kind"]])}</strong><p>{e(gap["explanation"])}</p></td></tr>')
    cards = []
    for gap in lesson["focused_gap_checklists"]:
        identifier = gap["id"]
        headings = "".join(f'<div><h4>Configuration {letter}</h4><span class="lab-lesson-state">{e(gap[side]["label"])}</span><p>{e(gap[side]["reason"])}</p></div>' for side, letter in (("left", "A"), ("right", "B")))
        pairs = []
        for pair in gap["checkpoint_pairs"]:
            columns = []
            for side, letter in (("left", "A"), ("right", "B")):
                row = pair[side]
                if row is None:
                    content = '<p class="compare-absent">This conditional checkpoint is not triggered here. Its absence supplies no authentic evidence; the real gap remains open.</p>'
                else:
                    content = f'<span class="lab-check-state">{e(checkpoint_labels.get(row["state"], row["state"]))}</span><p>{e(row["reason"])}</p>'
                columns.append(f'<div class="compare-check-cell"><h5>Configuration {letter}</h5>{content}</div>')
            marker = "Different checkpoint conditions" if pair["different"] else "Same checkpoint conditions"
            pairs.append(f'<section class="compare-check-pair' + (' different' if pair["different"] else '') + f'"><h4>{e(pair["factor"])}</h4><p class="small"><strong>{marker}.</strong> {e(pair["explanation"])}</p><div class="compare-columns">{"".join(columns)}</div></section>')
        receipts = "".join(f'<div><h4>Configuration {letter}: authentic receipt still required</h4><p>{e(gap[side]["real_receipt_needed"])}</p></div>' for side, letter in (("left", "A"), ("right", "B")))
        cards.append(f'<article class="comparison-gap" id="walkthrough-{e(identifier)}" tabindex="-1"><h3>{e(identifier)} · {e(gap["title"])}</h3><p class="comparison-difference">{e(difference_labels[gap["difference_kind"]])}</p><p>{e(gap["explanation"])}</p><div class="compare-columns comparison-gap-summary">{headings}</div>{"".join(pairs)}<aside class="notice"><div class="compare-columns">{receipts}</div><p>Actual {e(identifier)} remains open on both sides. No authentic receipt has been supplied.</p></aside><p><a href="{e(lesson["per_gap_urls"][identifier])}">Explore this checklist in the editable comparison</a></p></article>')
    return f'''<section id="walkthrough" class="walkthrough-view" aria-labelledby="walkthrough-heading"><p class="eyebrow">Guided fictional comparison</p><h2 id="walkthrough-heading">Learn to read a comparison, one change at a time</h2><p class="lead">Follow seven lessons that connect decisions and source assumptions to their checklist reasons. Read the illustrated pair, consider the question and reveal its explanation. You can open the same choices in the editable workbench at any point.</p><aside class="tutorial-notice"><strong>Fictional lessons only · real agency decisions remain pending.</strong><p>All twelve real gaps remain open. Neither side supplies authentic source records, appointments, approvals or measured results. No benchmark is run. Moving between lessons does not record progress, complete a check or submit a decision.</p></aside><p><a class="button" href="/tutorial-practice">Try guided practice with your own choices</a></p><nav class="walkthrough-nav" aria-label="Guided comparison steps">{steps}</nav><article id="walkthrough-lesson" class="walkthrough-lesson" tabindex="-1"><p class="eyebrow">Step {lesson["position"]} of {lesson["total"]}</p><h3>{e(lesson["title"])}</h3><p class="lead">{e(lesson["goal"])}</p><div class="two-col"><section class="panel"><h4>What to try</h4><p>{e(lesson["action"])}</p><p><a href="{e(lesson["workbench_form_url"])}">Edit the illustrated choices</a></p></section><section class="panel"><h4>What to look for</h4>{item_list(lesson["observe"])}<p><a href="{e(lesson["workbench_url"])}">Open this pair in the editable comparison</a></p></section></div><p class="small">Each lesson loads its own fixed illustrated pair. These links open exactly the shown choices; edits you make in the workbench are not carried into the next lesson. Use your browser's Back action to return here.</p><h4>Why the checklists respond this way</h4><p>{e(lesson["explanation"])}</p><h4>Different choices in this lesson</h4>{choices}<section class="walkthrough-question"><h4>Pause and consider</h4><p>{e(lesson["reflection_question"])}</p><details class="walkthrough-reflection"><summary>Reveal the explanation</summary><p>{e(lesson["reflection_answer"])}</p><p class="small">This is an explanation, with no grading, saved answer or readiness score.</p></details></section><p class="walkthrough-takeaway"><strong>Keep in mind:</strong> {e(lesson["takeaway"])}</p>{movement}<h4>Checklist effects across all twelve gaps</h4><p>These rows compare A with B within this lesson. They do not report changes to the real record or progress between lessons. Follow a gap link to inspect both complete checklists in the editable comparison.</p><div class="table-scroll walkthrough-effects"><table><caption>Checklist effects in this fictional lesson</caption><thead><tr><th scope="col">Gap</th><th scope="col">Configuration A</th><th scope="col">Configuration B</th><th scope="col">Checklist reasoning</th></tr></thead><tbody>{"".join(summaries)}</tbody></table></div><h4>Read the focused checkpoint pairs</h4>{"".join(cards)}{movement}</article><aside class="notice"><strong>The real evidence boundary is unchanged.</strong> Empirical checkpoints remain unresolved in G05 and G06 under every selection. The preserved verdict remains fail, with eighteen comparison rows and twelve unsupported null findings. Fictional coherence does not establish authenticity, performance or authority.</aside><p><a href="/tutorial-compare">Return to the comparison workbench</a> · <a href="/remediation">Read the captured open gaps</a></p></section>'''



