    groups = (("Decision choices", ("purpose", "decision_review", "practical")), ("Source assumptions", ("definitions", "rights", "vintage", "source_review")), ("Scope and delivery assumptions", ("protected_scope", "custody", "operations", "pilot", "governance")))
