            controls.append(f'<div class="practice-control"><label for="practice-{e(key)}">Practice: {e(meta["label"])}</label><select id="practice-{e(key)}" name="{e(key)}" aria-describedby="practice-help-{e(key)}">{options}</select><div id="practice-help-{e(key)}"><p class="small">{e(meta["description"])}</p><p class="small"><strong>Current applied choice:</strong> {e(current["value_label"])}</p></div></div>')
