        headings = "".join(f'<div><h4>{heading}</h4><span class="lab-lesson-state">{e(gap[side]["label"])}</span><p>{e(gap[side]["reason"])}</p></div>' for side, heading in (("left", "A · fixed reference"), ("right", "B · applied practice choices")))
        pairs = []
        for pair in gap["checkpoint_pairs"]:
            columns = []
