# This fixed stylesheet is embedded only in the independent status document.
# The handler allows its exact SHA-256 through CSP; no arbitrary inline styles.
STATUS_STYLES = """
:root{color-scheme:light;--ink:#142b39;--muted:#506571;--line:#d7e0e4;--teal:#075e5b;--bg:#f3f6f6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 'Segoe UI',Arial,sans-serif}a{color:var(--teal);text-underline-offset:3px}a:hover{color:#033e3d}a:focus-visible{outline:3px solid #237fbc;outline-offset:4px}.skip{position:absolute;left:12px;top:-70px;background:#fff;padding:8px}.skip:focus{top:8px}header{background:white;border-bottom:1px solid var(--line);padding:23px max(24px,calc((100% - 1100px)/2));display:flex;gap:18px;justify-content:space-between;align-items:center}header strong{font-size:17px}header span{font-size:12px;color:var(--muted)}.shell{max-width:1100px;margin:auto;padding:0 28px}.hero{padding:42px 0 24px}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:1.6px;color:var(--teal);font-weight:700;margin:0 0 10px}h1{font:500 clamp(34px,4.5vw,50px)/1.15 Georgia,serif;letter-spacing:-1px;margin:0 0 16px}.lead{font-size:18px;color:var(--muted);max-width:820px;margin:0}nav{display:flex;gap:24px;flex-wrap:wrap;border-bottom:1px solid var(--line);padding:0 0 18px;margin-bottom:26px;font-size:14px}nav a[aria-current]{font-weight:700}main{background:white;border:1px solid var(--line);border-radius:12px;padding:30px;margin-bottom:30px}.result{border:1px solid #b7d5cb;background:#edf6f2;border-left:4px solid #307561;border-radius:7px;padding:20px 22px;margin-bottom:24px}.result.unavailable{border-color:#e2bfbc;border-left-color:#9e302d;background:#fbf0ef}.result h2{font:500 28px/1.25 Georgia,serif;margin:0 0 10px}.result p{margin:0 0 9px}.result p:last-child{margin-bottom:0}.stamp{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.components{display:grid;gap:13px;margin:20px 0 28px}.component{border:1px solid var(--line);border-radius:8px;padding:18px 20px;display:grid;grid-template-columns:minmax(170px,1fr) minmax(0,2fr);gap:12px}.component h3{font-size:15px;margin:0}.component p{font-size:14px;color:var(--muted);margin:5px 0 0}.state{font-weight:600;font-size:14px;color:var(--teal)}.state.unavailable{color:#9e302d}.state.not_checked,.state.not_configured{color:#704d12}.notice{border:1px solid #e7d8b9;border-left:4px solid #b98627;background:#fff8e9;border-radius:5px;padding:15px 18px;font-size:13px;color:#5f4a22;margin:24px 0}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:24px}.panel{border:1px solid var(--line);border-radius:8px;padding:22px}.panel h2{font-size:17px;margin:0 0 12px}.panel p,.panel li{font-size:14px;color:var(--muted)}.panel ul{padding-left:20px;margin-bottom:0}.panel li+li{margin-top:10px}p{margin:0 0 14px}.download{margin:25px 0 0;font-size:14px}footer{font-size:11px;color:var(--muted);padding:0 0 28px;display:flex;justify-content:space-between;gap:20px}@media(max-width:700px){header{padding:18px 20px}header span{display:none}.shell{padding:0 16px}.hero{padding:30px 0 22px}.lead{font-size:16px}nav{gap:16px;font-size:13px}main{padding:20px 17px}.result{padding:18px 16px}.result h2{font-size:25px}.component{display:block;padding:17px}.component h3{margin-bottom:8px}.two-col{grid-template-columns:1fr;gap:16px}.panel{padding:18px}footer{display:block}footer span{display:block;margin-bottom:6px}}
"""


STATUS_LABELS = {"readiness_bundle": "Readiness bundle", "intake_report": "Evidence intake report", "review_packet": "Review packet"}
STATUS_STATES = {"matches_captured_bytes": ("Matches captured bytes", "The configured captured input passed its pinned integrity and consistency checks."), "unavailable": ("Unavailable", "Validation could not confirm this captured input. Its content is withheld."), "not_checked": ("Not checked", "A prerequisite input is unavailable. This dependent input was not checked."), "not_configured": ("Not configured", "This optional input is not configured for this local service.")}


def render_status_page(report):
    """Independent failure-safe view; accepts no snapshot or exception details."""
    available = report["result"] == "matches_captured_bytes"
    title = "Configured inputs match captured bytes" if available else "Captured-input validation unavailable"
    explanation = "The configured captured inputs passed this request's checks. Matching bytes establish no readiness, acceptance or authority." if available else "Ordinary views and downloads are withheld. Review the component states below and preserve the captured evidence before investigating."
    presentation_notice = ""
    restart_guidance = ""
    if report["schema"] == "local-presentation-integrity-status/2":
        presentation = report["presentation"]
        suspended = presentation["mode"] == "suspended"
        presentation_title = "Presentation suspended" if suspended else "Read-only presentation"
        presentation_explanation = "Captured views and downloads are withheld by this process's startup selection, even when the captured inputs match. The input checks below remain separate and continue on every request." if suspended else ("Captured views and downloads are available for this request. Their availability establishes no readiness, acceptance or authority." if presentation["captured_content"] == "available" else "Captured views and downloads are withheld because input validation is unavailable. This process was started in read-only presentation mode.")
        presentation_notice = f'<section class="result {"unavailable" if suspended or presentation["captured_content"] == "withheld" else ""}" aria-labelledby="presentation-heading"><h2 id="presentation-heading">{e(presentation_title)}</h2><p>{e(presentation_explanation)}</p></section>'
        restart_guidance = '<section class="panel"><h2>Manual presentation restart</h2><p>To change the presentation mode, stop the exact owned process and use a separately reviewed startup command. Verify the original recorded input pins before starting a new read-only presentation process. Preserve any failed copy and existing incident evidence.</p><p>Do not edit captured inputs or replace pins to make a restart pass. A restart does not resolve an agency incident, establish acceptance, restore authority or resume model delivery. This startup selection lasts only for its process; it is not a durable incident latch.</p></section>'
    rows = []
    for component in report["components"]:
        state = component["state"]
        label, reason = STATUS_STATES[state]
        rows.append(f'<article class="component"><h3>{e(STATUS_LABELS[component["id"]])}</h3><div><span class="state {e(state)}">{e(label)}</span><p>{e(reason)}</p></div></article>')
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Local captured-input status | Model assurance</title><style>{STATUS_STYLES}</style></head><body><a class="skip" href="#main">Skip to content</a><header><strong>Model assurance</strong><span>Local readiness workspace · read-only</span></header><div class="shell"><div class="hero"><p class="eyebrow">Local presentation integrity</p><h1>Local captured-input status</h1><p class="lead">Inspect the captured inputs used by this local service. While this local service is running, this page remains available when input validation fails.</p></div><nav aria-label="Readiness views"><a href="/readiness">Readiness workspace</a><a href="/local-status" aria-current="page">Local status</a><a href="/local-status">Check again</a></nav><main id="main">{presentation_notice}<section class="result {"" if available else "unavailable"}" aria-labelledby="result-heading"><h2 id="result-heading">{e(title)}</h2><p>{e(explanation)}</p><p class="stamp">Checked at {e(report["checked_at"])} · UTC · This request only</p></section><section aria-label="Captured input checks" class="components">{"".join(rows)}</section><aside class="notice"><strong>All 12 substantive gaps remain open.</strong> Agency decisions remain pending. Authorization effect: none. Readiness or acceptance is not established.</aside><div class="two-col"><section class="panel"><h2>What this check establishes</h2><p>The check covers only the configured captured readiness bundle, intake report and review packet. It verifies their pinned local bytes and the consistency checks defined by their readers.</p><p>Each request performs a fresh check. This is not an ongoing monitor or a service availability history. The check does not establish source truth, independent custody, wider platform health or production qualification.</p></section><section class="panel"><h2>When validation is unavailable</h2><ul><li>Preserve the captured inputs, recorded pins and existing evidence before investigating.</li><li>Use the separate project evidence records to compare the affected input with its captured version. Do not edit an input or replace a pin to make this page pass.</li><li>Return to this page after a separately reviewed recovery. A later match does not resolve an incident, restore authority or close a readiness gap.</li></ul></section></div>{restart_guidance}<p class="download"><a href="/api/local-status">Download a fresh status check as JSON</a></p></main><footer><span>General advisory book unchanged · Project evidence kept separate</span><span>No repair, approval or benchmark action</span></footer></div></body></html>'''
